('工具与下载链接准备中',array['Strumenti e link di download in preparazione','Tools and download links are being prepared'],3686,null,array[]::text[]),
('Windows 安装',array['Installazione di Windows','Windows installation'],3687,null,array[]::text[]),
('系统安装、启动盘制作与驱动工具。',array['Installazione del sistema, supporti di avvio e strumenti per i driver.','System installation, bootable media and driver tools.'],3688,null,array[]::text[]),
