create or replace function chinatech_v2_private.directory_phone_v2(raw text) returns text
language plpgsql immutable set search_path='' as $$
declare value text:=chinatech_v2_private.directory_trim(chinatech_v2_private.query_nfkc(coalesce(raw,''))); digits text; international text;
begin
 if value='' or length(value)>40 or not chinatech_v2_private.directory_phone_query(value) then return null; end if;
 digits:=regexp_replace(value,'[^0-9]','','g');
 international:=case when left(value,1)='+' then digits when left(value,2)='00' then substr(digits,3) else '39'||digits end;
 if international !~ '^[1-9][0-9]{6,14}$' or (left(value,1)<>'+' and left(value,2)<>'00' and length(digits)<7) then return null; end if;
 return '+'||international;
end $$;
revoke all on function chinatech_v2_private.directory_phone_v2(text)from public,anon,authenticated,chinatech_runtime;

create or replace function chinatech_v2_private.project_customer_directory(target_store uuid,kind text,target_id text,document jsonb,published boolean default true) returns void
language plpgsql set search_path='' as $$
declare item jsonb; normalized text; display_name text; event_key text; event_position integer;
begin
 if kind not in ('profile','repair','sale','history') then raise exception 'unsupported directory source'; end if;
 delete from chinatech_v2_private.customer_directory_sources where store_id=target_store and origin_kind=kind and origin_id=target_id;
 if document is null or not published then return; end if;
 if kind='sale' then
  for item,event_position in select value,ordinality::integer from jsonb_array_elements(coalesce(document->'sales','[]')) with ordinality loop
   normalized:=chinatech_v2_private.directory_phone_v2(item->>'customerPhone');
   if normalized is null then continue; end if;
   display_name:=chinatech_v2_private.directory_trim(item->>'customerName'); if display_name in ('未填写姓名','未填写称呼','未记录') then display_name:=''; end if;
   event_key:=item->>'id';
  end loop;
 else
  normalized:=chinatech_v2_private.directory_phone_v2(case when kind='history' then document->>'customerPhone' else document->>'phone' end);
  if normalized is null then return; end if;
  display_name:=chinatech_v2_private.directory_trim(case when kind='profile' then document->>'name' else document->>'customerName' end);
  if display_name in ('未填写姓名','未填写称呼','未记录') then display_name:=''; end if;
   case when kind='history' then '' else coalesce(document->>'email','') end,
   case when kind='repair' then coalesce(document->>'createdAt','') when kind='history' then coalesce(document->>'intakeAt','') else '' end,
   case when kind='history' then coalesce((document->>'sourceRow')::integer,0) else 0 end,
   case when kind='repair' then coalesce(nullif(document->>'updatedAt',''),document->>'createdAt','') when kind='history' then coalesce(nullif(document->>'pickupDate',''),left(document->>'intakeAt',10),'') else '' end);
 end if;
end $$;
revoke all on function chinatech_v2_private.project_customer_directory(uuid,text,text,jsonb,boolean)from public,anon,authenticated,chinatech_runtime;

create or replace function chinatech_v2_private.customer_record_fact_prepared(kind text,document jsonb,event_position integer,prepared jsonb)returns jsonb
language plpgsql immutable strict set search_path=''as $$
declare phone text;event_at text;summary jsonb;search text;item jsonb;field text;field_value text;previews jsonb:='[]';faults jsonb;raw_values text[];refunded bigint;device_name text;
begin
 if kind='repairs'then
  phone:=chinatech_v2_private.directory_phone_v2(document->>'phone');event_at:=document->>'createdAt';
  select coalesce(jsonb_agg(left(value,200)order by ordinal),'[]')into faults from jsonb_array_elements_text(coalesce(document->'faults','[]'))with ordinality a(value,ordinal);
  summary:=jsonb_build_object('kind',kind,'id',document->>'id','brand',document->>'brand','model',document->>'model','createdAt',event_at,'issue',document->>'issue','rework',document?'repairOrigin');
  if document?'faults'then summary:=summary||jsonb_build_object('faults',faults);end if;
  if document?'issueNote'then summary:=summary||jsonb_build_object('issueNote',document->>'issueNote');end if;
  if exists(select 1 from jsonb_array_elements_text(coalesce(document->'faults','[]'))v where length(v)>200)then previews:=previews||'"faults"'::jsonb;end if;
  raw_values:=array[document->>'id',document->>'brand',document->>'model',document->>'issue',document->>'issueNote',(select string_agg(a.value,' 'order by a.ordinal)from jsonb_array_elements_text(coalesce(document->'faults','[]'))with ordinality a(value,ordinal)),event_at];
 elsif kind='sales'then
  item:=document->'sale';phone:=chinatech_v2_private.directory_phone_v2(item->>'customerPhone');event_at:=item->>'time';
  device_name:=case when item?'product'then chinatech_v2_private.directory_trim(coalesce(item->'product'->>'brand','')||' '||coalesce(item->'product'->>'model',''))else chinatech_v2_private.directory_trim(coalesce(document->>'brand','')||' '||coalesce(document->>'model',''))end;
  select coalesce(sum((value->>'amountCents')::bigint)filter(where (coalesce(value->'void','null')='null'::jsonb or value->'void'='false'::jsonb)),0)into refunded from jsonb_array_elements(coalesce(item->'refunds','[]'));
  summary:=jsonb_build_object('kind',kind,'id',item->>'id','unitId',document->>'id','unitCode',coalesce(nullif(item->'product'->>'code',''),document->>'code'),'deviceName',device_name,'time',event_at,'priceCents',item->'priceCents','paidCents',item->'paidCents','delivered',item->'delivered','customerName',coalesce(item->>'customerName',''),'customerEmail',coalesce(item->>'customerEmail',''),'customerAddress',coalesce(item->>'customerAddress',''),'customerNote',coalesce(item->>'customerNote',''),'refundedCents',refunded,'returned',case jsonb_typeof(item->'returned')when 'boolean'then(item->>'returned')::boolean when 'null'then false else item?'returned'end,'afterSaleCount',jsonb_array_length(coalesce(item->'afterSales','[]')));
  if item?'deliveryDate'then summary:=summary||jsonb_build_object('deliveryDate',item->>'deliveryDate');end if;
  raw_values:=array[document->>'code',summary->>'unitCode',device_name,item->>'id',item->>'customerName',item->>'customerEmail',item->>'customerAddress',item->>'customerNote',event_at,item->>'deliveryDate'];
 elsif kind='history'then
  phone:=chinatech_v2_private.directory_phone_v2(document->>'customerPhone');event_at:=document->>'intakeAt';
  summary:=jsonb_build_object('kind',kind,'id',document->>'id','sourceRow',document->'sourceRow','sourceStatus',document->'sourceStatus','brand',document->'brand','model',document->'model','intakeAt',event_at,'pickupDate',document->'pickupDate','salePriceCents',document->'salePriceCents','reviewCount',jsonb_array_length(coalesce(document->'reviewReasons','[]')));
  raw_values:=array['ST-'||lpad(((document->>'sourceRow')::integer-1)::text,greatest(4,length(((document->>'sourceRow')::integer-1)::text)),'0'),document->>'brand',document->>'model',document->>'sourceStatus',document->>'customerName',document->>'customerPhone',document->>'intakeAt',document->>'pickupDate'];
 else raise exception'unsupported customer record source';end if;
 if phone is null then return null;end if;
 foreach field in array array['brand','model','issue','issueNote','unitCode','deviceName','customerName','customerEmail','customerNote','sourceStatus']loop
  field_value:=summary->>field;if field_value is not null and length(field_value)>200 then summary:=summary||jsonb_build_object(field,left(field_value,200));previews:=previews||to_jsonb(field);end if;
 end loop;
 search:=chinatech_v2_private.customer_record_search(raw_values,prepared);
 return jsonb_build_object('phone',phone,'eventAt',event_at,'search',search,'summary',summary||jsonb_build_object('previews',previews));
end $$;

revoke all on function chinatech_v2_private.customer_record_fact_prepared(text,jsonb,integer,jsonb)from public,anon,authenticated,chinatech_runtime;

create or replace function chinatech_v2_private.project_procurement_list(target_store uuid,target_id text,document jsonb,model text,cancelled boolean) returns void
language plpgsql set search_path='' as $$
declare events jsonb:=coalesce(document->'events','[]'::jsonb); arrived_count integer; ordered boolean; last_cart text; phase text;
begin
 if document is null then
  delete from chinatech_v2_private.procurement_list_sources where store_id=target_store and id=target_id;
  return;
 end if;
 select coalesce(sum(case when value->>'type' in ('arrival','correction') then (value->>'quantity')::integer else 0 end),0)::integer,
  coalesce(bool_or(value->>'type'='ordered'),false)
 into arrived_count,ordered from jsonb_array_elements(events);
 select value->>'type' into last_cart from jsonb_array_elements(events) with ordinality where value->>'type' in ('cart_added','cart_removed') order by ordinality desc limit 1;
 phase:=case when not ordered then case when last_cart='cart_added' then 'cart' else 'draft' end
  when arrived_count=(document->>'quantity')::integer then 'complete' when arrived_count>0 then 'partial' else 'ordered' end;
 values(target_store,target_id,document->>'repairId',model,document->>'item',document->>'supplier',(document->>'quantity')::integer,arrived_count,phase,coalesce(document->>'expectedAt',''),jsonb_array_length(events),document?'supplierId',document->>'supplierId',document->>'specification',cancelled,chinatech_v2_private.unicode17_lower(target_id||' '||(document->>'item')||' '||(document->>'supplier')||' '||(document->>'repairId')||' '||coalesce(model,'')))
 on conflict(store_id,id) do update set repair_id=excluded.repair_id,repair_model=excluded.repair_model,item=excluded.item,supplier=excluded.supplier,
 quantity=excluded.quantity,arrived=excluded.arrived,status=excluded.status,expected_at=excluded.expected_at,ledger_revision=excluded.ledger_revision,
 has_supplier_id=excluded.has_supplier_id,supplier_id=excluded.supplier_id,specification=excluded.specification,repair_cancelled=excluded.repair_cancelled,search_v2=excluded.search_v2;
end $$;
revoke all on function chinatech_v2_private.project_procurement_list(uuid,text,jsonb,text,boolean)from public,anon,authenticated,chinatech_runtime;

create or replace function chinatech_v2_private.project_repair_list(target_store uuid,target_id text) returns void
language plpgsql set search_path='' as $$
declare document jsonb;wf jsonb;rows jsonb;facts jsonb;summary jsonb;
begin
 select data,workflow into document,wf from chinatech_v2_private.repair_intakes where store_id=target_store and id=target_id;
 if document is null then delete from chinatech_v2_private.repair_list_sources where store_id=target_store and id=target_id;
 else
  -- Only the target's real dependency set. No whole-store canonical snapshot,
  -- costs, event bodies, photos or signatures enter the list projection.
  select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'item',s.item,'supplier',s.supplier,'specification',s.specification,'quantity',s.quantity,'arrived',s.arrived,'status',s.status,'ledgerRevision',s.ledger_revision,'required',p.data->'required','requirementId',p.data->'requirementId','requirementRevision',p.data->'requirementRevision') order by p.id),'[]') into rows
  from chinatech_v2_private.procurement_records p join chinatech_v2_private.procurement_list_sources s on s.store_id=p.store_id and s.id=p.id where p.store_id=target_store and p.repair_id=target_id;
  facts:=chinatech_v2_private.repair_list_facts(document,wf,rows);
  summary:=jsonb_build_object('id',target_id,'category',document->>'category','model',document->>'model','customerName',coalesce(nullif(document->>'customerName',''),'未填写姓名'),'customerNameMissing',chinatech_v2_private.directory_trim(document->>'customerName')='','phone',document->>'phone','priority',document->>'priority','rework',document?'repairOrigin','createdAt',document->>'createdAt','updatedAt',greatest(document->>'updatedAt',coalesce(wf->>'updatedAt',document->>'updatedAt')),'stage',facts->'stage','history',facts->'history','workflowGroup',facts->'workflowGroup','partsGroup',facts->'parts'->'group','progress',facts->'progress','contact',facts->'contact','chips',facts->'chips','chipCount',facts->'chipCount','suppliers',facts->'suppliers','suppliersPreview',facts->'suppliersPreview');
  values(target_store,target_id,document->>'createdAt',summary->>'updatedAt',case document->>'priority' when '紧急' then 0 when '优先' then 1 else 2 end,facts->>'stage',(facts->>'history')::boolean,(facts->>'currentHandover')::boolean,(facts->'contact'->>'collectedUnpaid')::boolean,facts->>'workflowGroup',facts->'parts'->>'group',(facts->>'pickupNotice') like '已通知%',chinatech_v2_private.unicode17_lower(concat_ws(' ',target_id,summary->>'customerName',document->>'phone',document->>'brand',document->>'model',document->>'serial',document->>'issue')),summary)
  on conflict(store_id,id) do update set created_at=excluded.created_at,updated_at=excluded.updated_at,priority=excluded.priority,stage=excluded.stage,history=excluded.history,current_handover=excluded.current_handover,collected_unpaid=excluded.collected_unpaid,workflow_group=excluded.workflow_group,parts_group=excluded.parts_group,notified=excluded.notified,search=excluded.search,summary=excluded.summary;
 end if;
end $$;
revoke all on function chinatech_v2_private.project_repair_list(uuid,text)from public,anon,authenticated,chinatech_runtime;

create or replace function chinatech_v2_private.retail_list_search_v2(input_values text[],labels text[]) returns text
language plpgsql stable set search_path='' as $$
declare base text; extra text[]:='{}'; value text; language integer;
begin
 base:=chinatech_v2_private.unicode17_lower(chinatech_v2_private.directory_trim(chinatech_v2_private.unicode17_nfkc(array_to_string(input_values,' ',''))));
 foreach value in array labels loop
  if value is not null and value<>'' then
   for language in 0..2 loop extra:=array_append(extra,chinatech_v2_private.retail_list_translate(value,language));end loop;
  end if;
 end loop;
 return chinatech_v2_private.unicode17_lower(chinatech_v2_private.unicode17_nfkc(base||' '||array_to_string(extra,' ')));
end $$;
revoke all on function chinatech_v2_private.retail_list_search_v2(text[],text[])from public,anon,authenticated,chinatech_runtime;

