language sql immutable set search_path='' as $$
 select encode(sha256(convert_to(chinatech_v2_private.unicode17_upper(regexp_replace(chinatech_v2_private.unicode17_nfkc(coalesce(value,'')),E'[\u0009\u000a\u000b\u000c\u000d\u0020\u00a0\u1680\u2000-\u200a\u2028\u2029\u202f\u205f\u3000\ufeff]','','g')),'UTF8')),'hex')
$$;
revoke all on function chinatech_v2_private.retail_identifier_hash_v2(text)from public,anon,authenticated,chinatech_runtime;

create or replace function chinatech_v2_private.project_retail_list(target_store uuid,target_id text,kind text,document jsonb,original jsonb,visible boolean) returns void
language plpgsql set search_path='' as $$
declare rowkey text:=kind||':'||target_id; title text; code text; category text; status text; spec text; facts jsonb; sale jsonb; labels text[]; parts text[]; note_index integer;
begin
 if document is null or not visible then delete from chinatech_v2_private.retail_list_sources where store_id=target_store and key=rowkey;return;end if;
 title:=coalesce(nullif(array_to_string(array_remove(array_remove(array[document->>'brand',document->>'model'],null),''),' '),''),'商品名称未记录');
 if kind='history' then
  code:='ST-'||lpad(((document->>'sourceRow')::integer-1)::text,greatest(4,length(((document->>'sourceRow')::integer-1)::text)),'0');
  category:=coalesce(nullif(document->>'category',''),'未记录');status:=case when document->>'sourceStatus'='以售' then '已售' else coalesce(nullif(document->>'sourceStatus',''),'状态未记录') end;
  spec:=document->>'memory';
  labels:=array[category,document->>'condition',document->>'color',status];
  parts:=array[code,title,document->>'sourceStatus',status,document->>'condition',document->>'customerName',document->>'customerPhone',document->>'category',document->>'color',spec,document->>'identifier',null,document->>'intakeAt',document->>'pickupDate'];note_index:=12;
 else
  code:=document->>'code';category:=('{"phone":"手机","tablet":"平板","laptop":"笔记本","desktop":"台式电脑","console":"游戏机","other":"其他商品"}'::jsonb)->>(document->>'category');
  status:=('{"inspecting":"待检测","available":"可售","reserved":"已预留","hold":"暂停销售","sold":"已售出"}'::jsonb)->>(document->>'status');
  if document->>'status'='sold' then
   if coalesce(document->>'currentSaleId','')<>'' then select value into sale from jsonb_array_elements(document->'sales') where value->>'id'=document->>'currentSaleId' limit 1;
   else sale:=document->'sales'->-1;end if;
  end if;
  spec:=chinatech_v2_private.retail_list_spec(document);
  if spec='规格待确认' and coalesce(original->>'memory','')<>'' then spec:=original->>'memory';end if;
  if document->>'ramGb' is not null or document->>'bodyStorage' is not null or jsonb_array_length(document->'disks')>0 or coalesce(document->>'edition','')<>'' then
   facts:=jsonb_build_object('category',document->'category','ramGb',document->'ramGb','bodyStorage',document->'bodyStorage','disks',document->'disks','edition',document->'edition');
  end if;
  labels:=array[category,document->>'condition',document->>'color',status];
  parts:=array[code,title,document->>'condition',category,document->>'color',spec,document->>'imei1',document->>'imei2',document->>'serial',document->>'productCode',document->>'knownIssues',document->>'location',document->>'intakeDate',original->>'memory',original->>'identifier',original->>'customerName',original->>'customerPhone',null,sale->>'customerName',sale->>'customerPhone',sale->>'deliveryDate',document->'reservation'->>'name',document->'reservation'->>'phone'];note_index:=18;
 end if;
 values(target_store,rowkey,target_id,kind,visible,case when kind='unit' then document->'historyOrigin'->>'recordId' else null end,
